import * as THREE from './vendor/three.module.js';
import {defaults,validate,pose,orbitEnd,verticalFov,pathLength} from './motion.js';
import {installLearning} from './learning.js';
const $=id=>document.getElementById(id), V=(x,y,z)=>new THREE.Vector3(x,y,z);
let state=defaults(), selected='start', t=0, playing=false, nav=false, mapScale=22, mapCenter=V(0,0,3), last=0, frames=0;
const scene=new THREE.Scene();scene.background=new THREE.Color('#b7d7e4');scene.fog=new THREE.Fog('#b7d7e4',45,130);
scene.add(new THREE.HemisphereLight(0xffffff,0x907c61,2.3));const sun=new THREE.DirectionalLight(0xffead2,3);sun.position.set(-10,25,12);scene.add(sun);
function mesh(geo,color,x,y,z,parent=scene){const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color,roughness:0.8}));m.position.set(x,y,z);parent.add(m);return m;}
mesh(new THREE.BoxGeometry(100,0.2,80),0xd6bc8e,0,-0.12,15);mesh(new THREE.BoxGeometry(130,0.12,90),0x398eaa,0,-0.05,-55);
for(let i=0;i<12;i++)mesh(new THREE.BoxGeometry(100,0.025,0.18),0x9bc6d0,0,0.02,-7-i*3.5);
for(const [x,z,s] of [[-6,3,1.5],[5,-5,1.2],[-10,-10,2],[9,9,0.8],[-3,8,0.6]]){const r=mesh(new THREE.DodecahedronGeometry(s,0),0x88877b,x,s*0.45,z);r.scale.y=.65;}
for(const [x,z] of [[-9,7],[10,1],[-14,-3]]){mesh(new THREE.CylinderGeometry(.13,.25,5,8),0x806344,x,2.5,z);for(let j=0;j<5;j++){const leaf=mesh(new THREE.ConeGeometry(.55,3.8,5),0x4a8766,x,5,z);leaf.rotation.z=1.1;leaf.rotation.y=j*Math.PI*2/5;}}
mesh(new THREE.BoxGeometry(3,2.2,3),0xc9986e,12,1.1,-12);const roof=mesh(new THREE.ConeGeometry(3,1.6,4),0x735950,12,3,-12);roof.rotation.y=Math.PI/4;
const person=new THREE.Group();scene.add(person);mesh(new THREE.SphereGeometry(.18,12,10),0xe1b08c,0,1.65,0,person);mesh(new THREE.CylinderGeometry(.23,.19,.66,10),0xcb5f4a,0,1.15,0,person);
const limbs=[];for(const [x,y,color] of [[-.13,.8,0x243848],[.13,.8,0x243848],[-.3,1.4,0xe1b08c],[.3,1.4,0xe1b08c]]){const g=new THREE.Group();g.position.set(x,y,0);person.add(g);mesh(new THREE.CylinderGeometry(.07,.065,.65,8),color,0,-.3,0,g);limbs.push(g);}
const camera=new THREE.PerspectiveCamera(50,16/9,.05,200);const mapCamera=new THREE.OrthographicCamera(-20,20,20,-20,.1,200);mapCamera.up.set(0,0,-1);
let previewRenderer,mapRenderer;
try{previewRenderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});mapRenderer=new THREE.WebGLRenderer({antialias:true});}catch(e){$('engine').textContent='WebGL을 초기화하지 못했습니다.';throw e;}
for(const r of [previewRenderer,mapRenderer]){r.setPixelRatio(Math.min(devicePixelRatio,1.75));r.outputColorSpace=THREE.SRGBColorSpace;}
$('preview').prepend(previewRenderer.domElement);$('stage').append(mapRenderer.domElement);
const markers=new THREE.Group();scene.add(markers);const markerA=mesh(new THREE.SphereGeometry(.4),0x8ee6c6,0,0,0,markers),markerB=mesh(new THREE.SphereGeometry(.4),0xffc16c,0,0,0,markers),current=mesh(new THREE.ConeGeometry(.33,.85,5),0xf9f9f5,0,0,0,markers);current.rotation.x=Math.PI/2;
const pathLine=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:0x204f46}));markers.add(pathLine);
const arrow=new THREE.ArrowHelper(V(0,0,-1),V(0,1,0),2,0xffffff,.5,.25);markers.add(arrow);
const frustum=new THREE.CameraHelper(camera);frustum.material.color?.set(0xffffff);markers.add(frustum);
function message(s){$('message').textContent=s;}
function sync(){if(state.mode==='orbit')state.end={...orbitEnd(state)};for(const id of ['mode','focal','duration','arc','yaw','pitch','frameX','aimY'])$(id).value=state[id];for(const id of ['track','ease','walk'])$(id).checked=state[id];for(const id of ['x','z'])$(id).value=state[selected][id].toFixed(1);$('height').value=state[selected].y;for(const [id,val]of [['heightVal',state[selected].y.toFixed(1)+' m'],['arcVal',state.arc+'°'],['focalVal',state.focal+' mm'],['durationVal',state.duration+' s'],['yawVal',state.yaw+'°'],['pitchVal',state.pitch+'°'],['frameXVal',Math.round(state.frameX*100)+'%'],['aimYVal',state.aimY.toFixed(1)+' m']])$(id).textContent=val;$('arcLabel').hidden=state.mode!=='orbit';$('direction').hidden=state.track;$('startPick').classList.toggle('active',selected==='start');$('endPick').classList.toggle('active',selected==='end');const points=Array.from({length:101},(_,i)=>{const p=pose(state,i/100);return V(p.x,.12,p.z);});pathLine.geometry.dispose();pathLine.geometry=new THREE.BufferGeometry().setFromPoints(points);markerA.position.set(state.start.x,.45,state.start.z);markerB.position.set(state.end.x,.45,state.end.z);}
function resize(){for(const [r,el]of [[previewRenderer,$('preview')],[mapRenderer,$('stage')]])r.setSize(el.clientWidth,el.clientHeight,false);const aspect=$('stage').clientWidth/$('stage').clientHeight;mapCamera.left=-mapScale*aspect/2;mapCamera.right=mapScale*aspect/2;mapCamera.top=mapScale/2;mapCamera.bottom=-mapScale/2;mapCamera.position.set(mapCenter.x,60,mapCenter.z);mapCamera.lookAt(mapCenter.x,0,mapCenter.z);mapCamera.updateProjectionMatrix();}
new ResizeObserver(resize).observe($('preview'));new ResizeObserver(resize).observe($('stage'));
function positionSubject(s,q){person.position.x=s.walk?(-1+2*q)*(s.walkDirection??1):0;limbs.forEach((g,i)=>g.rotation.x=s.walk?Math.sin(q*s.duration*5+(i%2)*Math.PI)*.45:0);scene.updateMatrixWorld(true);}
function configureCamera(c,s,q){const p=pose(s,q);c.position.set(p.x,p.y,p.z);c.fov=verticalFov(s.focal);c.updateProjectionMatrix();if(s.track){c.lookAt(person.position.x,s.aimY??1.1,0);c.rotateY(Math.atan((s.frameX??0)*36/(2*s.focal)));}else{c.rotation.order='YXZ';c.rotation.set(s.pitch*Math.PI/180,s.yaw*Math.PI/180,0);}c.updateMatrixWorld();return p;}
function render(){positionSubject(state,t);const p=configureCamera(camera,state,t);
camera.updateMatrixWorld();current.position.set(p.x,.6,p.z);const dir=camera.getWorldDirection(V(0,0,0));current.rotation.z=-Math.atan2(dir.x,-dir.z);arrow.position.set(p.x,.7,p.z);arrow.setDirection(dir);frustum.update();markers.visible=false;previewRenderer.render(scene,camera);markers.visible=true;mapRenderer.render(scene,mapCamera);$('timeline').value=t;$('timeBadge').textContent=(t*state.duration).toFixed(1)+'s';$('metrics').textContent=`X ${p.x.toFixed(1)} · Y ${p.y.toFixed(1)} · Z ${p.z.toFixed(1)} m | 경로 ${pathLength(state).toFixed(1)} m | 평균 ${(pathLength(state)/state.duration).toFixed(2)} m/s | 수평 화각 ${(2*Math.atan(36/(2*state.focal))*180/Math.PI).toFixed(1)}°`;frames++;}
function tick(now){if(playing){t=Math.min(1,t+Math.min((now-last)/1000,.1)/state.duration);if(t===1){playing=false;$('play').textContent='▶ 재생';}}last=now;render();requestAnimationFrame(tick);}sync();resize();requestAnimationFrame(tick);$('engine').textContent='WebGL · 실시간 3D';
function stop(){playing=false;$('play').textContent='▶ 재생';}
for(const id of ['focal','duration','arc','yaw','pitch','frameX','aimY'])$(id).oninput=()=>{state[id]=Number($(id).value);sync();};
$('mode').onchange=()=>{stop();state.mode=$('mode').value;sync();};
for(const id of ['track','ease','walk'])$(id).onchange=()=>{state[id]=$(id).checked;sync();};
function setPosition(x,z){const p=state[selected];if(state.mode==='orbit'&&selected==='end'){const a=Math.atan2(x,z)-Math.atan2(state.start.x,state.start.z);state.arc=THREE.MathUtils.clamp(a*180/Math.PI,-300,300);}else{p.x=THREE.MathUtils.clamp(x,-30,30);p.z=THREE.MathUtils.clamp(z,-30,30);if(state.mode==='orbit'&&Math.hypot(p.x,p.z)<1){p.z=1;message('Orbit 반경은 최소 1m로 유지합니다.');}}sync();}
for(const id of ['x','z'])$(id).onchange=()=>{const v=Number($(id).value);if(!Number.isFinite(v))return sync();setPosition(id==='x'?v:state[selected].x,id==='z'?v:state[selected].z);};
$('height').oninput=()=>{state[selected].y=Number($('height').value);sync();};
for(const [id,pick]of [['startPick','start'],['endPick','end']])$(id).onclick=()=>{selected=pick;sync();};
$('presetD').onclick=()=>{stop();state=defaults();t=0;sync();message('Dolly 예시를 불러왔습니다. 자유롭게 수정하세요.');};
$('presetO').onclick=()=>{stop();state={...defaults(),mode:'orbit',start:{x:-7,y:1.6,z:7},arc:100,walk:false};t=0;sync();message('Orbit 예시: 시작 반경을 유지하며 인물 주위를 회전합니다.');};
$('play').onclick=()=>{if(t>=1)t=0;playing=!playing;$('play').textContent=playing?'Ⅱ 일시정지':'▶ 재생';};$('restart').onclick=()=>{t=0;playing=true;$('play').textContent='Ⅱ 일시정지';};for(const [id,value]of [['toStart',0],['toEnd',1]])$(id).onclick=()=>{stop();t=value;};$('timeline').oninput=()=>{stop();t=Number($('timeline').value);};
let grid=true;$('grid').onclick=()=>{grid=!grid;$('guides').hidden=!grid;$('grid').textContent='삼분할 '+(grid?'ON':'OFF');};
for(const [id,value]of [['editMode',false],['navMode',true]])$(id).onclick=()=>{nav=value;$('editMode').classList.toggle('active',!nav);$('navMode').classList.toggle('active',nav);$('hint').textContent=nav?'드래그로 촬영장 이동 · 두 손가락 핀치로 확대/축소':'A/B 점을 드래그하거나 빈 공간을 터치해 선택한 지점을 이동하세요. Orbit 종료점은 같은 반경의 호 위로 이동합니다.';};
$('fit').onclick=()=>{mapScale=22;mapCenter.set(0,0,3);resize();};
const pointers=new Map();const canvas=mapRenderer.domElement;const ray=new THREE.Raycaster();const plane=new THREE.Plane(V(0,1,0),0);let pinch=0;
function ground(e){const r=canvas.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),mapCamera);return ray.ray.intersectPlane(plane,V(0,0,0));}
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);return;}if(!nav){stop();const p=ground(e);if(!p)return;const da=Math.hypot(p.x-state.start.x,p.z-state.start.z),db=Math.hypot(p.x-state.end.x,p.z-state.end.z);if(Math.min(da,db)<1.2)selected=da<db?'start':'end';setPosition(p.x,p.z);}};
canvas.onpointermove=e=>{const previous=pointers.get(e.pointerId);if(!previous)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch>0&&d>0){mapScale=THREE.MathUtils.clamp(mapScale*pinch/d,8,70);resize();}pinch=d;return;}if(nav){const r=canvas.getBoundingClientRect();mapCenter.x-=(e.clientX-previous.x)/r.height*mapScale;mapCenter.z-=(e.clientY-previous.y)/r.height*mapScale;resize();}else{const p=ground(e);if(p)setPosition(p.x,p.z);}};
function release(e){pointers.delete(e.pointerId);pinch=0;}canvas.onpointerup=release;canvas.onpointercancel=release;canvas.onlostpointercapture=release;canvas.onwheel=e=>{e.preventDefault();mapScale=THREE.MathUtils.clamp(mapScale*Math.exp(e.deltaY*.001),8,70);resize();};
$('save').onclick=()=>{try{localStorage.setItem('cct-shot-v1',JSON.stringify(state));message('촬영 설정을 이 브라우저에 저장했습니다.');}catch{message('저장 공간에 접근할 수 없습니다. JSON 백업을 사용하세요.');}};
$('load').onclick=()=>{try{const raw=localStorage.getItem('cct-shot-v1');if(!raw)throw Error('저장된 촬영이 없습니다.');state=validate(JSON.parse(raw));stop();t=0;sync();message('저장된 촬영을 불러왔습니다.');}catch(e){message(e.message);}};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='camera-shot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('JSON 파일이 너무 큽니다.');state=validate(JSON.parse(await file.text()));stop();t=0;sync();message('JSON 촬영 설정을 복원했습니다.');}catch(e){message(e.message);}e.target.value='';};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>message('오프라인 설치를 활성화하지 못했습니다. 온라인 촬영은 계속 사용할 수 있습니다.'));
const trainer=window.__trainer={snapshot:()=>({state:structuredClone(state),t,playing,frames,pose:pose(state,t),camera:camera.position.toArray(),fov:camera.fov,drawCalls:previewRenderer.info.render.calls,mapScale}),set:(s)=>{state=validate(s);sync();},seek:(q)=>{stop();t=q;render();}};

const environment=scene.children.filter(o=>o.isMesh);const probe=new THREE.PerspectiveCamera(50,16/9,.05,200);
function sample(s,q){positionSubject(s,q);configureCamera(probe,s,q);const box=new THREE.Box3().setFromObject(person);const corners=[];for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z])corners.push(V(x,y,z).project(probe));const xs=corners.map(p=>(p.x+1)/2),ys=corners.map(p=>(1-p.y)/2);const left=Math.min(...xs),right=Math.max(...xs),top=Math.min(...ys),bottom=Math.max(...ys);const inFront=corners.every(p=>p.z>=-1&&p.z<=1);let occluded=false;for(const height of [1.1,1.65]){const target=V(person.position.x,height,0),delta=target.clone().sub(probe.position),distance=delta.length();const sight=new THREE.Raycaster(probe.position,delta.normalize(),.05,distance-.2);if(sight.intersectObjects(environment,false).length)occluded=true;}
const subjectDistance=probe.position.distanceTo(V(person.position.x,1,0));const foreground=[];for(const obj of environment){if(obj.geometry.type==='BoxGeometry'&&obj.geometry.parameters.width>20)continue;const center=new THREE.Box3().setFromObject(obj).getCenter(V(0,0,0));if(probe.position.distanceTo(center)>=subjectDistance-.3)continue;const pt=center.clone().project(probe);if(pt.z>=-1&&pt.z<=1&&Math.abs(pt.x)<1.2&&Math.abs(pt.y)<1.2)foreground.push({id:obj.id,x:(pt.x+1)/2});}
const bg=V(12,1.5,-12).project(probe);const heading=probe.getWorldDirection(V(0,0,0));const horizonPoint=probe.position.clone().add(V(heading.x,0,heading.z).normalize().multiplyScalar(10000));horizonPoint.y=0;const horizon=(1-horizonPoint.project(probe).y)/2;const forward=V(person.position.x+.1*(s.walkDirection??1),1.1,0).project(probe),origin=V(person.position.x,1.1,0).project(probe);return {t:q,horizon,motionRight:forward.x>origin.x,centerX:(left+right)/2,height:bottom-top,leftSpace:left,rightSpace:1-right,inside:inFront&&left>=0&&right<=1&&top>=0&&bottom<=1,occluded,foreground,backgroundX:(bg.x+1)/2,penalty:(inFront?0:10)+Math.max(0,-left,right-1,-top,bottom-1)+(occluded?2:0)};}
trainer.analyze=s=>{const samples=Array.from({length:41},(_,i)=>sample(s,i/40));render();return{samples,meta:{length:pathLength(s),maxHeight:Math.max(s.start.y,s.end.y),walk:s.walk,mode:s.mode,arc:s.arc}};};
trainer.capture=(s,q)=>{const old=state,oldT=t;state=validate(s);t=q;render();const image=previewRenderer.domElement.toDataURL('image/png');state=old;t=oldT;render();return image;};
trainer.set=(s)=>{stop();state=validate(s);t=0;sync();render();};
trainer.seek=q=>{stop();t=Math.min(1,Math.max(0,q));render();};
installLearning(trainer);
